CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE races(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,distance_km REAL NOT NULL,race_date TEXT NOT NULL,goal_seconds INTEGER NOT NULL,target_source TEXT NOT NULL DEFAULT 'user',active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE shoes(id INTEGER PRIMARY KEY AUTOINCREMENT,brand TEXT NOT NULL DEFAULT '',model TEXT NOT NULL,nickname TEXT NOT NULL DEFAULT '',start_km REAL NOT NULL DEFAULT 0,archived INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE runs(id INTEGER PRIMARY KEY AUTOINCREMENT,external_id TEXT UNIQUE,started_at TEXT NOT NULL,ended_at TEXT,distance_km REAL NOT NULL,duration_s REAL NOT NULL,avg_hr REAL,elevation_m REAL,calories REAL,source TEXT NOT NULL DEFAULT 'manual',rpe INTEGER,shoe_id INTEGER,notes TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(shoe_id) REFERENCES shoes(id) ON DELETE SET NULL);
CREATE INDEX idx_runs_started_at ON runs(started_at);
CREATE TABLE health_metrics(id INTEGER PRIMARY KEY AUTOINCREMENT,external_id TEXT UNIQUE,metric_type TEXT NOT NULL,start_at TEXT NOT NULL,end_at TEXT,value REAL NOT NULL,unit TEXT NOT NULL DEFAULT '',source TEXT NOT NULL DEFAULT 'apple_health',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_health_metric_time ON health_metrics(metric_type,start_at);
CREATE TABLE workouts(id INTEGER PRIMARY KEY AUTOINCREMENT,week_start TEXT NOT NULL,origin_week_start TEXT NOT NULL,scheduled_date TEXT NOT NULL,workout_type TEXT NOT NULL,title TEXT NOT NULL,distance_km REAL NOT NULL,pace_low_s_per_km REAL,pace_high_s_per_km REAL,details_json TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL DEFAULT 'planned',linked_run_id INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(linked_run_id) REFERENCES runs(id) ON DELETE SET NULL);
CREATE INDEX idx_workouts_week ON workouts(week_start);
CREATE TABLE performance_marks(id INTEGER PRIMARY KEY AUTOINCREMENT,distance_km REAL NOT NULL,duration_s REAL NOT NULL,mark_date TEXT NOT NULL,source TEXT NOT NULL DEFAULT 'manual',label TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE prediction_history(id INTEGER PRIMARY KEY AUTOINCREMENT,race_distance_km REAL NOT NULL,predicted_seconds REAL NOT NULL,low_seconds REAL NOT NULL,high_seconds REAL NOT NULL,confidence REAL NOT NULL,source TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE suggestions(id INTEGER PRIMARY KEY AUTOINCREMENT,suggestion_type TEXT NOT NULL,title TEXT NOT NULL,rationale TEXT NOT NULL,payload_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,resolved_at TEXT);
CREATE TABLE chat_messages(id INTEGER PRIMARY KEY AUTOINCREMENT,role TEXT NOT NULL,text TEXT NOT NULL,meta_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ai_usage(id INTEGER PRIMARY KEY AUTOINCREMENT,usage_kind TEXT NOT NULL,model TEXT NOT NULL,input_tokens INTEGER NOT NULL DEFAULT 0,output_tokens INTEGER NOT NULL DEFAULT 0,web_searches INTEGER NOT NULL DEFAULT 0,estimated_cost_eur REAL NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE plan_reviews(id INTEGER PRIMARY KEY AUTOINCREMENT,week_start TEXT NOT NULL UNIQUE,review_text TEXT NOT NULL,sources_json TEXT NOT NULL DEFAULT '[]',suggestion_id INTEGER,model TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(suggestion_id) REFERENCES suggestions(id) ON DELETE SET NULL);
